/** Earned, optional body histories. No level/stat sheet is copied between lives. */
export const HERO_TRANSFORMATIONS=Object.freeze([
 {id:'ceramic-arm',name:'Kiln-grown arm',color:'#d9bc8a',verb:'Anchor a crossing',description:'A repaired ceramic limb can hold a one-use crossing shield without consuming a brace.',tradeoff:'Anchoring occupies the tool hand until the shield breaks or expires. Ordinary physical blows deal 10% less damage.',cost:5},
 {id:'reed-ear',name:'Reed-tuned ear',color:'#a9c58f',verb:'Hear the hesitation',description:'Living reeds distinguish the moving parts of a charged attack and give the crew one extra moment.',tradeoff:'Electrical and sonic hits deal 15% more damage. Each creature can be read once in an encounter.',cost:5},
 {id:'ash-shadow',name:'Ash-bound shadow',color:'#baafd2',verb:'Step through ash',description:'Step to a nearby reachable tile and leave a brief silhouette to catch an attack already aimed at the old position.',tradeoff:'The step costs seven MP and leaves you exposed for five seconds. The echo only catches one already-aimed attack.',cost:7}
]);
const ids=HERO_TRANSFORMATIONS.map(x=>x.id),def=id=>HERO_TRANSFORMATIONS.find(x=>x.id===id),clone=x=>JSON.parse(JSON.stringify(x));
const text=(x,max=100)=>typeof x==='string'?x.slice(0,max):'';
const integer=(n,a=0,b=6)=>Number.isInteger(n)&&n>=a&&n<=b;
const point=p=>p&&Number.isFinite(p.x)&&Number.isFinite(p.y)&&Math.abs(p.x)<10000&&Math.abs(p.y)<10000;
const distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
const entry=id=>({id,deeds:[],unlocked:[],equipped:null,signature:null,attuned:false});
const root=()=>({version:1,heroes:Array.from({length:7},(_,id)=>entry(id)),settled:[]});
function signature(p){if(!p||typeof p!=='object')return null;const out={id:text(p.id,96),name:text(p.name||p.sourceLabel,100),kind:text(p.kind,40),shape:text(p.shape,24),family:text(p.family,60)};return out.id&&out.name?out:null;}
function validSignature(p){return p===null||p&&typeof p==='object'&&Object.keys(p).every(k=>['id','name','kind','shape','family'].includes(k))&&typeof p.id==='string'&&p.id.length>0&&p.id.length<=96&&typeof p.name==='string'&&p.name.length>0&&p.name.length<=100&&['kind','shape','family'].every(k=>typeof p[k]==='string'&&p[k].length<=60);}
function normalizedEntry(value,id){const out=entry(id);if(!value||typeof value!=='object')return out;out.unlocked=[...new Set((Array.isArray(value.unlocked)?value.unlocked:[]).filter(v=>ids.includes(v)))];out.equipped=out.unlocked.includes(value.equipped)?value.equipped:null;out.attuned=value.attuned===true||out.equipped!==null;out.signature=signature(value.signature);const seen=new Set();for(const d of Array.isArray(value.deeds)?value.deeds.slice(-32):[]){if(!d||typeof d.id!=='string'||!d.id||seen.has(text(d.id,96)))continue;seen.add(text(d.id,96));out.deeds.push({id:text(d.id,96),kind:text(d.kind,32),goal:text(d.goal,40),label:text(d.label,160)});}return out;}
export function normalizeHeroLegacies(value){const out=root();if(!value||typeof value!=='object')return out;out.heroes=out.heroes.map((_,id)=>normalizedEntry(Array.isArray(value.heroes)?value.heroes.find(h=>h?.id===id):null,id));out.settled=[...new Set((Array.isArray(value.settled)?value.settled:[]).filter(v=>typeof v==='string'&&v.length>0&&v.length<=104))].slice(-128);return out;}
export function validHeroLegacies(value){if(value==null)return true;if(value.version!==1||!Array.isArray(value.heroes)||value.heroes.length!==7||!Array.isArray(value.settled)||value.settled.length>128||new Set(value.settled).size!==value.settled.length||value.settled.some(v=>typeof v!=='string'||!v||v.length>104))return false;return value.heroes.every((h,id)=>h&&h.id===id&&typeof h.attuned==='boolean'&&Array.isArray(h.unlocked)&&h.unlocked.length<=3&&new Set(h.unlocked).size===h.unlocked.length&&h.unlocked.every(v=>ids.includes(v))&&(h.equipped===null||h.unlocked.includes(h.equipped)&&h.attuned)&&validSignature(h.signature)&&Array.isArray(h.deeds)&&h.deeds.length<=32&&new Set(h.deeds.map(d=>d?.id)).size===h.deeds.length&&h.deeds.every(d=>d&&typeof d.id==='string'&&d.id.length>0&&d.id.length<=96&&typeof d.kind==='string'&&d.kind.length<=32&&typeof d.goal==='string'&&d.goal.length<=40&&typeof d.label==='string'&&d.label.length<=160));}
function ensure(s){if(!s.heroLegacies)s.heroLegacies=root();return s.heroLegacies;}
const who=event=>event?.heroId??event?.hero;
function earnedForm(type,goal){if(type==='repair'||type==='objective'&&['regulator','supply'].includes(goal))return 'ceramic-arm';if(type==='objective'&&['escort','signal'].includes(goal)||type==='ecology'&&['rescue','soothe','listen','befriend','feed','peace'].includes(goal))return 'reed-ear';if(['knowledge','scouting'].includes(type)||type==='ecology'&&['redirect','lure','divert','rival'].includes(goal))return 'ash-shadow';if(type==='ecology'&&goal==='repair')return 'ceramic-arm';return null;}
/** Caller supplies an actual settled result; a source event can reward each hero once. */
export function recordLegacyDeed(state,event={}){const hero=who(event),type=event.type||event.kind,goal=event.goal||event.objectiveKind||event.action||(event.type?event.kind:'')||'',form=earnedForm(type,goal),id=text(event.id,96);if(!state||!integer(hero)||!id||event.success===false||!form)return {added:false,unlocked:null};const s=ensure(state),h=s.heroes[hero],key=hero+':'+id;if(s.settled.includes(key)||h.deeds.some(d=>d.id===id))return {added:false,unlocked:null};s.settled.push(key);s.settled=s.settled.slice(-128);h.deeds.push({id,kind:text(type,32),goal:text(goal,40),label:text(event.label||({objective:'Kept the worksite safe',knowledge:'Learned a rule of the old machinery',scouting:'Found a safer approach',ecology:'Made room for another life',repair:'Restored a working mechanism'})[type],160)});h.deeds=h.deeds.slice(-32);if(event.pattern){const p=signature(event.pattern);if(p)h.signature=p;}const fresh=!h.unlocked.includes(form);if(fresh)h.unlocked.push(form);syncHeroLegacies(state);return {added:true,unlocked:fresh?form:null,hero,summary:legacySummary(state,hero)};}
/** First attunement is free; later changes spend one Ether. Leaving a form is free. */
export function equipLegacy(state,id,transformation){if(!state||!integer(id)||state.mode!=='field')return false;const s=ensure(state),h=s.heroes[id];if(transformation!==null&&!h.unlocked.includes(transformation))return false;if(h.equipped===transformation)return false;if(transformation!==null&&h.attuned){if(!(state.items?.ether>=1))return false;state.items.ether--;}h.equipped=transformation;if(transformation!==null)h.attuned=true;syncHeroLegacies(state);return true;}
export function legacySummary(state,id){if(!integer(id))return null;const h=state?.heroLegacies?.heroes?.[id]||entry(id),t=def(h.equipped);return {hero:id,equipped:h.equipped,traitName:t?.name||'Unchanged form',description:t?.description||'Earn a body history through the work you choose to do.',tradeoff:t?.tradeoff||'',unlocked:[...h.unlocked],deed:h.deeds.at(-1)?.label||'',deeds:h.deeds.length,signature:h.signature?.name||'',visual:h.equipped,firstAttunement:!h.attuned};}
export function syncHeroLegacies(state){if(!state?.heroes||!state.heroLegacies)return;for(const h of state.heroes){const t=state.heroLegacies?.heroes?.[h.id]?.equipped;h.legacy=t&&ids.includes(t)?{transformation:t}:null;}}
/** Drop-in carries earned identity while keeping the receiving world's supplies. */
export function copyHeroLegacy(target,source,id){if(!integer(id))return false;const s=ensure(target),incoming=normalizeHeroLegacies(source?.heroLegacies).heroes[id],existing=s.heroes[id],deeds=new Map([...existing.deeds,...incoming.deeds].map(d=>[d.id,d]));s.heroes[id]={...incoming,deeds:[...deeds.values()].slice(-32),unlocked:[...new Set([...existing.unlocked,...incoming.unlocked])],attuned:existing.attuned||incoming.attuned,signature:incoming.signature||existing.signature};if(!s.heroes[id].equipped)s.heroes[id].equipped=existing.equipped;syncHeroLegacies(target);return true;}

function runtimeHero(b,h){return b.legacy?.heroes?.find(v=>v.id===h?.id);}
export function prepareLegacyBattle(b){const persistent=normalizeHeroLegacies(b.context?.heroLegacies);b.legacy={version:1,enabled:!b.context?.friendly&&!b.context?.tutorial,heroes:(b.heroes||[]).map(h=>({id:h.id,equipped:persistent.heroes[h.id]?.equipped||null,uses:0,heard:[]})),anchors:[],shadows:[]};for(const h of b.heroes||[]){const t=runtimeHero(b,h)?.equipped;h.legacy=t?{transformation:t}:null;}return b.legacy;}
export function validLegacyBattle(value,heroes=[]){if(value==null)return true;if(value.version!==1||typeof value.enabled!=='boolean'||!Array.isArray(value.heroes)||value.heroes.length!==heroes.length||!Array.isArray(value.anchors)||value.anchors.length>3||!Array.isArray(value.shadows)||value.shadows.length>3)return false;const actorIds=new Set(heroes.map(h=>h.id));if(new Set(value.heroes.map(h=>h?.id)).size!==value.heroes.length||value.heroes.some(h=>!actorIds.has(h?.id)||h.equipped!==null&&!ids.includes(h.equipped)||!integer(h.uses,0,2)||!Array.isArray(h.heard)||h.heard.length>8||new Set(h.heard).size!==h.heard.length||h.heard.some(v=>typeof v!=='string'&&typeof v!=='number')))return false;for(const list of [value.anchors,value.shadows]){if(new Set(list.map(x=>x?.ownerId)).size!==list.length)return false;for(const a of list)if(!point(a)||!actorIds.has(a.ownerId)||!integer(a.charges,0,1)||!Number.isFinite(a.expiresAt)||a.expiresAt<0||a.expiresAt>1e9)return false;}return value.anchors.every(a=>value.heroes.find(h=>h.id===a.ownerId)?.equipped==='ceramic-arm')&&value.shadows.every(a=>value.heroes.find(h=>h.id===a.ownerId)?.equipped==='ash-shadow');}
export function advanceLegacyBattle(b){if(!b.legacy)return;for(const list of [b.legacy.anchors,b.legacy.shadows])for(const a of list)if(a.expiresAt<=b.time)a.charges=0;}
export function legacyAllowsTool(b,h){return !b.legacy?.anchors?.some(a=>a.ownerId===h?.id&&a.charges>0&&a.expiresAt>b.time);}
function floorSet(b){const cells=b.context?.walkable||b.objective?.walkable||b.context?.objective?.walkable;return Array.isArray(cells)?new Set(cells.map(p=>Array.isArray(p)?Math.floor(p[0])+','+Math.floor(p[1]):Math.floor(p.x)+','+Math.floor(p.y))):null;}
function stepDestination(b,h,target){const open=floorSet(b);if(!open||!point(h))return null;const cx=Math.floor(h.x),cy=Math.floor(h.y),occupied=[...(b.heroes||[]),...(b.enemies||[]),...(b.objective?.asset?[b.objective.asset]:[])].filter(a=>a!==h&&a.hp>0&&!a.withdrawn),options=[[cx+1,cy],[cx-1,cy],[cx,cy+1],[cx,cy-1]].map(([x,y])=>({x:x+.5,y:y+.5})).filter(p=>open.has(Math.floor(p.x)+','+Math.floor(p.y))&&occupied.every(a=>distance(a,p)>.65));return options.sort((a,z)=>{const da=target&&point(target)?distance(a,target):distance(a,h),dz=target&&point(target)?distance(z,target):distance(z,h);return dz-da||a.x-z.x||a.y-z.y;})[0]||null;}
function check(b,h,target,request){if(!b?.legacy?.enabled)return 'Body histories are quiet during this encounter.';if(!h||h.hp<=0||!(b.heroes||[]).includes(h))return 'Choose a living traveller.';const r=runtimeHero(b,h),t=def(r?.equipped);if(!t)return 'Earn and attune a body history from the character entry screen.';if(b.ended)return 'This encounter has ended.';if(h.atb<1)return 'Wait for a ready action.';if(r.uses>=2)return 'This body history has been used twice in this encounter.';if(h.mp<t.cost)return 'Needs '+t.cost+' MP.';if(request.action==='anchor'){if(t.id!=='ceramic-arm')return 'Attune the kiln-grown arm.';if(h.fieldGear)return 'Drop the carried tool before anchoring.';if(!legacyAllowsTool(b,h))return 'The arm is already holding a crossing.';if(!point(h)||!point(target)||target.hp<=0||(b.heroes||[]).includes(target))return 'Choose a living creature to face.';return '';}
 if(request.action==='listen'){if(t.id!=='reed-ear')return 'Attune the reed-tuned ear.';if(!target||target.hp<=0||!(b.enemies||[]).includes(target)||!target.intent||!['strike','alarm','objective-sabotage','objective-steal','objective-advance','ecology-grudge'].includes(target.intent.kind))return 'Choose a creature with a charged threat.';if(distance(h,target)>6)return 'Move within six tiles to hear the moving parts.';if(r.heard.includes(target.id))return 'This creature has already been read.';return '';}
 if(request.action==='ash-step'){if(t.id!=='ash-shadow')return 'Attune the ash-bound shadow.';if(!stepDestination(b,h,target))return 'No unoccupied adjacent floor is reachable.';return '';}
 return 'Choose an available body-history action.';}
export function legacyActions(b,h,target){const r=runtimeHero(b,h),t=def(r?.equipped);if(!t||!b?.legacy?.enabled)return[];const action=({'ceramic-arm':'anchor','reed-ear':'listen','ash-shadow':'ash-step'})[t.id],reason=check(b,h,target,{action}),p=action==='ash-step'?stepDestination(b,h,target):null;return [{system:'legacy',action,label:t.verb,detail:t.description+' '+t.tradeoff+' Costs one ready action and '+t.cost+' MP; twice per encounter.'+(p?' Destination '+p.x.toFixed(1)+', '+p.y.toFixed(1)+'.':''),enabled:!reason,reason,...(p?{preview:p}:{})}];}
const emit=(b,action,actor,target,label)=>b.event?.({type:'legacy',action,actor,target,label});
export function legacyCommand(b,h,target,request={}){if(check(b,h,target,request))return false;const r=runtimeHero(b,h),t=def(r.equipped);if(request.action==='anchor'){const dx=target.x-h.x,dy=target.y-h.y,l=Math.hypot(dx,dy)||1;b.legacy.anchors=b.legacy.anchors.filter(a=>a.ownerId!==h.id);b.legacy.anchors.push({ownerId:h.id,x:h.x+dx/l*.8,y:h.y+dy/l*.8,charges:1,expiresAt:b.time+12});emit(b,'anchor',h,target,'Kiln-grown arm holds the crossing');}
 if(request.action==='listen'){target.intent.left+=.8;target.intent.total+=.8;r.heard.push(target.id);emit(b,'listen',h,target,target.intent.label+' · one hesitation revealed');}
 if(request.action==='ash-step'){const p=stepDestination(b,h,target),old={x:h.x,y:h.y};b.legacy.shadows=b.legacy.shadows.filter(a=>a.ownerId!==h.id);b.legacy.shadows.push({ownerId:h.id,...old,charges:1,expiresAt:b.time+8});h.x=p.x;h.y=p.y;h.status??={};h.status.exposed=Math.max(h.status.exposed||0,5);emit(b,'ash-step',h,target,'A silhouette remains where the attack was aimed');}
 h.mp-=t.cost;h.atb=0;r.uses++;return true;}
export function modifyLegacyDamage(b,caster,target,amount,opts={}){let out=amount;if(runtimeHero(b,caster)?.equipped==='ceramic-arm'&&opts.physical&&!opts.dot&&!opts.secondary)out*=.9;if(runtimeHero(b,target)?.equipped==='reed-ear'&&(opts.core==='volt'||opts.tech?.core==='volt'||opts.sonic===true||/sonic|hymn|bell|chorus/i.test(opts.tech?.name||'')))out*=1.15;return out;}
export function interceptLegacyHit(b,attacker,intent,target){if(!b.legacy?.enabled||!point(attacker)||!point(target)||!((b.heroes||[]).includes(target)||target.team==='heroes')||!['line','single'].includes(intent?.shape)||distance(attacker,target)<1.8)return false;const dx=target.x-attacker.x,dy=target.y-attacker.y,len2=dx*dx+dy*dy;for(const a of b.legacy.anchors){if(a.charges<=0||a.expiresAt<=b.time)continue;const u=((a.x-attacker.x)*dx+(a.y-attacker.y)*dy)/len2;if(u>.08&&u<.96&&Math.hypot(a.x-(attacker.x+u*dx),a.y-(attacker.y+u*dy))<=.8){a.charges=0;const owner=b.heroes.find(h=>h.id===a.ownerId);emit(b,'anchor-block',owner||target,attacker,'Ceramic crossing catches the attack');return true;}}
 const a=b.legacy.shadows.find(a=>a.ownerId===target.id&&a.charges>0&&a.expiresAt>b.time&&intent.target===target.id&&Number.isFinite(intent.x)&&Number.isFinite(intent.y)&&Math.hypot(intent.x-a.x,intent.y-a.y)<.8&&distance(a,target)>.75);if(!a)return false;a.charges=0;emit(b,'shadow-decoy',target,attacker,'The aimed attack spends itself on ash');return true;}
/** Modest additions follow the sprite's existing foot pivot. */
export function drawHeroLegacy(renderer,actor,T=48){const t=actor?.legacy?.transformation;if(!ids.includes(t)||!point(actor)||!renderer?.ctx)return;const c=renderer.ctx,x=actor.x*T,y=actor.y*T,time=renderer.time||0;c.save();c.lineCap='round';c.lineJoin='round';if(t==='ceramic-arm'){c.strokeStyle='#7f6951';c.lineWidth=6;c.beginPath();c.moveTo(x+9,y-T*.63);c.lineTo(x+14,y-T*.36);c.lineTo(x+8,y-T*.23);c.stroke();c.strokeStyle='#dfc799';c.lineWidth=3;c.beginPath();c.moveTo(x+9,y-T*.63);c.lineTo(x+14,y-T*.36);c.lineTo(x+8,y-T*.23);c.stroke();c.strokeStyle='#947e59';c.lineWidth=1;for(let i=0;i<3;i++){c.beginPath();c.moveTo(x+10+i,y-T*.53+i*4);c.lineTo(x+15+i,y-T*.55+i*4);c.stroke();}}
 if(t==='reed-ear'){c.strokeStyle='#5d7959';c.lineWidth=2.4;for(let i=0;i<3;i++){c.beginPath();c.moveTo(x-7,y-T*.91);c.quadraticCurveTo(x-12-i*2,y-T*(1.08+i*.03),x-9-i*3,y-T*(1.21+i*.02));c.stroke();}c.fillStyle='#c5d3a3';c.beginPath();c.ellipse(x-10,y-T*1.04,3,5,-.5,0,Math.PI*2);c.fill();}
 if(t==='ash-shadow'){c.fillStyle='#77708a55';c.beginPath();c.ellipse(x-5+Math.sin(time*2)*2,y+4,T*.32,T*.10,-.1,0,Math.PI*2);c.fill();c.strokeStyle='#b5a7c376';c.lineWidth=1.3;for(let i=0;i<3;i++){c.beginPath();c.moveTo(x-14-i*3,y+1);c.quadraticCurveTo(x-18-i*4,y-6-i*2,x-16-i*5,y-14-i*4);c.stroke();}}c.restore();}
